const $=s=>document.querySelector(s),esc=s=>String(s??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');const drafts=new Map();let renderedPath='';let data=null,current='',layout='split',baseline='head',tree=false,busy=false,timer;
const stateLabel={pending:'○ 待审查',reviewed:'✓ 已审查',issue:'⚑ 有问题',recheck:'↻ 待复审'};
function toast(t){$('#toast').textContent=t;$('#toast').classList.remove('hidden');clearTimeout(timer);timer=setTimeout(()=>$('#toast').classList.add('hidden'),4500)}
function file(){return data?.files.find(f=>f.path===current)}
async function api(path,body){const r=await fetch(path,body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:undefined);const v=await r.json();if(!r.ok)throw Error(v.error||'请求失败');return v}
async function refresh(){if(busy)return;busy=true;$('#refresh').textContent='读取中…';try{const selected=current;data=await api('/api/snapshot');current=data.files.some(f=>f.path===selected)?selected:data.files[0]?.path||'';render();$('#refresh').textContent='↻ 刷新仓库';}catch(e){toast(e.message);$('#refresh').textContent='↻ 重试读取'}finally{busy=false}}
function view(id){document.querySelectorAll('main > section').forEach(e=>e.classList.toggle('visible',e.id===id));document.querySelectorAll('.nav[data-view]').forEach(e=>e.classList.toggle('active',e.dataset.view===id))}
function renderList(){if(!data)return;const q=$('#search').value.toLowerCase(),state=$('#filter').value;const filtered=data.files.filter(f=>f.path.toLowerCase().includes(q)&&(state==='all'||(state==='issue'?['issue','recheck'].includes(f.state):f.state===state)));const groups=Map.groupBy?Map.groupBy(filtered,f=>tree?f.path.split('/').slice(0,-1).join('/'):'工作区变更'):new Map([['工作区变更',filtered]]);$('#filelist').innerHTML=[...groups].map(([group,items])=>`<div class="group">⌄ ${esc(group)}<span class="count">${items.length}</span></div>`+items.map(f=>`<button class="file ${f.path===current?'active':''}" data-file="${esc(f.path)}" title="${esc(f.path)}"><span class="filetag">${f.status==='??'?'A':'M'}</span><span class="name">${esc(f.path.split('/').pop())}</span><span class="state ${f.state==='reviewed'?'green':f.state==='pending'?'muted':'amber'}">${stateLabel[f.state].split(' ')[0]}</span></button><div class="filemeta"><span class="green">+${f.plus}</span> −${f.minus} · ${stateLabel[f.state].slice(2)}</div>`).join('')).join('')||'<div class="empty">没有匹配的文件</div>';document.querySelectorAll('[data-file]').forEach(b=>b.onclick=()=>{current=b.dataset.file;renderFile();renderList()})}
function patchRows(patch){const sections=[];let section=null,old=0,next=0,deletes=[],adds=[];function flush(){if(!section)return;for(let i=0;i<Math.max(deletes.length,adds.length);i++)section.rows.push([deletes[i]||null,adds[i]||null]);deletes=[];adds=[]}for(const line of patch.split('\n')){if(line.startsWith('@@')){flush();const m=line.match(/^@@ -(\d+)(?:,\d+)? \+(\d+)(?:,\d+)? @@/);if(!m)continue;old=+m[1];next=+m[2];section={title:line,rows:[]};sections.push(section)}else if(section){const type=line[0],text=line.slice(1);if(type==='-')deletes.push({n:old++,text,kind:'del'});else if(type==='+')adds.push({n:next++,text,kind:'add'});else if(type===' '){flush();section.rows.push([{n:old++,text,kind:''},{n:next++,text,kind:''}])}}}flush();return sections}
function comparisonPatch(old,newText){const a=old.split('\n'),b=newText.split('\n');if(a.at(-1)==='')a.pop();if(b.at(-1)==='')b.pop();let start=0;while(start<Math.min(a.length,b.length)&&a[start]===b[start])start++;if(start===a.length&&start===b.length)return '';let endA=a.length,endB=b.length;while(endA>start&&endB>start&&a[endA-1]===b[endB-1]){endA--;endB--}const before=Math.max(0,start-4),afterA=Math.min(a.length,endA+4),afterB=Math.min(b.length,endB+4);return `@@ -${before+1},${afterA-before} +${before+1},${afterB-before} @@ 相对上次记录\n`+a.slice(before,start).map(l=>' '+l).concat(a.slice(start,endA).map(l=>'-'+l),b.slice(start,endB).map(l=>'+'+l),b.slice(endB,afterB).map(l=>' '+l)).join('\n')}
function renderDiff(){const f=file(),target=$('#codegrid');if(!f){target.style.display='block';target.innerHTML='<div class="empty">工作区没有未提交变更。可以在外部 Agent 中修改后刷新。</div>';return}target.style.display='block';if(f.binary||f.blocked){target.innerHTML='<div class="empty">此文件为二进制、链接或超过 2 MB，请在外部工具中检查。</div>';return}if(layout==='document'){target.innerHTML='<div class="docsection">'+f.content.split('\n').map((l,i)=>`<div class="docline"><span class="ln">${i+1}</span><span class="code">${esc(l)||' '}</span></div>`).join('')+'</div>';return}if(baseline==='previous'&&f.previous===null){target.innerHTML='<div class="empty">此文件尚无审查记录。先完成一轮审查；之后在外部修改并刷新，即可与这次内容对比。</div>';return}const patch=baseline==='previous'?comparisonPatch(f.previous,f.content):f.patch;const sections=patchRows(patch);target.innerHTML=sections.map(s=>`<div class="hunk">${esc(s.title)}</div><div class="aligned-diff">${s.rows.map(row=>`<div class="diffrow">${row.map(r=>`<div class="line ${r?.kind||(!r?'blank':'')}"><span class="ln">${r?.n??''}</span><span class="code">${esc(r?.text??'')}</span></div>`).join('')}</div>`).join('')}</div>`).join('')||'<div class="empty">相对上次审查记录没有内容变化。</div>'}
function renderFile(){const f=file();$('.diffpane').classList.toggle('newfile',f?.status==='??'&&baseline==='head');$('#filepath').textContent=f?.path||'无未提交变更';$('#filestat').textContent=f?`+${f.plus} −${f.minus}`:'';$('#purpose').textContent=f?.status==='??'?'新增文件 · 未跟踪':'工作区与 HEAD 的真实变更';$('#explanation').textContent=f?'来源未知 · 这些修改尚未关联 Agent 会话。可在右侧保存审查问题或复制上下文交给外部 Agent。':'保持此页打开，在外部修改后刷新。';$('#hunk').classList.add('hidden');$('#righthead').textContent=layout==='document'?'当前文件全文':'当前工作区 · 本次读取';$('.diffheads div:first-child').textContent=baseline==='previous'?'上次审查记录':'HEAD · '+(data?.base.slice(0,8)||'');$('.diffheads').style.display=layout==='document'?'none':'grid';$('#reviewstate').textContent=f?stateLabel[f.state]:'';$('#approve').textContent=f?.state==='reviewed'?'撤销审查标记':'✓ 标记已审查';$('#approve').disabled=!f||f.binary||f.blocked;$('#flag').disabled=!f;if(renderedPath!==current){$('.diffscroll').scrollTop=0;renderedPath=current}$('#prompt').value=drafts.get(current)??f?.note??'';$('#commentcontext').textContent=f?`反馈绑定：${f.path.split('/').pop()} · ${f.fingerprint.slice(0,8)}`:'';renderDiff();$('#diffmode').textContent=layout==='document'?'双栏 Diff':'阅读全文';$('#baseline').value=baseline;}
function render(){renderList();renderFile();const done=data.files.filter(f=>f.state==='reviewed').length,issues=data.files.filter(f=>f.state==='issue').length,again=data.files.filter(f=>f.state==='recheck').length;$('#progressText').textContent=`${done} / ${data.files.length} 已审查`;$('#progress').style.width=`${data.files.length?done/data.files.length*100:0}%`;$('#batchstatus').textContent=again?`${again} 个待复审`:issues?`${issues} 个有问题`:done===data.files.length?'审查完成':'待审查';$('#snapshot').textContent='读取于 '+new Date(data.capturedAt).toLocaleTimeString();$('.summary').children[0].textContent=`${data.files.length} 个文件`;$('.summary .green').textContent='+'+data.files.reduce((n,f)=>n+f.plus,0);$('.summary .mono.muted').textContent='−'+data.files.reduce((n,f)=>n+f.minus,0);$('#checksummary').textContent='未运行项目测试';$('#checksummary').className='muted';$('#staginginfo').textContent=`人工记录：${issues} 个问题 · ${again} 个待复审 · 保存在客户端`;$('.top .pill').textContent='⑂ '+data.branch;$('.sidebar .branch.current').textContent='⑂ '+data.branch;$('.nav[data-view="review"] .count').textContent=data.files.length;$('#workspace').innerHTML=`<div class="breadcrumb">LOCAL REPOSITORY / 实际数据</div><h1>fde-study</h1><p class="subtitle mono">${esc(data.repo)}</p><div class="workspaceitem"><div><h2>当前未提交修改</h2><p class="muted">${data.files.length} 个文件 · 来源未知 · 分支 ${esc(data.branch)}</p></div><span class="spacer"></span><button class="primary" id="enterReview">继续审查 →</button></div><div class="context" style="margin-top:25px"><b>试用这一轮真实修改</b><p>1. 先读 W01 复盘新增文件，熟悉上下文。</p><p>2. 查看 W02 两份笔记的真实 Diff，记录遗漏或不清楚的内容。</p><p>3. 在右侧保存问题，复制反馈给你现有的 Claude Code / Codex。</p><p>4. 外部修改后点击“刷新仓库”，查看待复审和相对上次记录的变化。</p><p class="muted">此试用版只读取 Git，不暂存、不提交，也不会自动启动 Agent。</p></div>`;$('#enterReview').onclick=()=>view('review');$('#logrows').innerHTML=data.history.map((h,i)=>`<tr><td class="blue mono">${i?'│':'●'}</td><td>${esc(h.subject)}</td><td>${esc(h.author)}</td><td class="mono muted">${esc(h.hash)}</td><td class="muted">${esc(h.date)}</td></tr>`).join('');$('#commitdetail').textContent='真实 git log · 试用版暂不提供历史提交文件联动';$('#liveOverview').textContent=`本轮 ${data.files.length} 个文件 · ${done} 个已审查 · ${issues} 个问题 · ${again} 个待复审`;}
async function mark(state,note=''){const f=file();if(!f)return;try{await api('/api/review',{path:f.path,fingerprint:f.fingerprint,state,note});drafts.delete(f.path);await refresh();toast(state==='issue'?'问题已保存，并绑定当前文件内容':'审查记录已保存')}catch(e){toast(e.message)}}
function exportReview(){if(!data)return;const text=`# fde-study 审查记录\n\n仓库：${data.repo}\n基线：${data.base}\n时间：${data.capturedAt}\n\n`+data.files.map(f=>`## ${f.path}\n\n状态：${stateLabel[f.state]}\n内容指纹：${f.fingerprint}\n\n${f.note||'无问题记录'}\n`).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:'text/markdown;charset=utf-8'}));a.download='fde-study-review.md';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
$('.repo').textContent='▣  fde-study';$('.top .tools').innerHTML='<button class="outline" id="refresh">↻ 刷新仓库</button>';$('.top > .muted').textContent='实际仓库 · 只读 Git';$('h1').textContent='审查这一轮，真实的修改。';$('.breadcrumb').textContent='fde-study / 当前工作区';$('.subtitle').innerHTML='W01 复盘与 W02 课程笔记 &nbsp;·&nbsp; 来源未知 &nbsp;·&nbsp; <span id="snapshot">正在读取…</span>';$('.eyebrow + .nav .count').textContent='1';$('.sidebar .branch.current').textContent='⑂ 当前分支（读取中）';$('.sidebar .branch:not(.current)').textContent='工作区与 HEAD 对比';document.querySelectorAll('.sidebar .branch').forEach((e,i)=>{if(i>1)e.classList.add('hidden')});document.querySelectorAll('.agentmini').forEach(e=>e.classList.add('hidden'));$('.eyebrow').textContent='WORKSPACE';$('#connect').textContent='↗ 复制反馈给 Agent';document.querySelectorAll('.sidebar .eyebrow')[2].textContent='AGENT 未关联';$('.filebar label').classList.add('hidden');$('.filebar .filetag').textContent='MD';$('.files > .muted').textContent='真实 Git 变更 · 来源未知';$('#incremental').outerHTML='<select id="baseline" aria-label="对比基线" style="background:#292c32;color:#bbc3d0;border:1px solid #434750;border-radius:4px;padding:5px"><option value="head">相对 HEAD</option><option value="previous">相对上次审查</option></select><button id="diffmode">阅读全文</button>';$('.seg #intent').textContent='全部变更';$('#intent').classList.add('selected');$('.agenthead').innerHTML='<div class="avatar">✓</div><div>审查工作台<div class="muted" style="font-size:10px;margin-top:3px">记录问题 · 交接外部 Agent</div></div><span class="spacer"></span><button id="closeAgent" aria-label="关闭审查面板">×</button>';$('#toggleAgent').textContent='☷ 审查面板';$('#chat').innerHTML='<div class="eyebrow" style="padding:0;margin-top:0">THIS REVIEW</div><h2 style="font-size:16px;line-height:1.8">先理解变化，再判断内容。</h2><p class="muted" style="font-size:12px;line-height:1.9">这里展示的是 fde-study 的真实未提交修改，包含中文长文档和新增文件。</p><div class="reviewcard message"><b>建议从哪里开始</b>先看 W01 复盘直播，再审查 W02 的两篇笔记；README 的索引变更可以最后确认。</div><div class="reviewcard message"><b>给 Agent 的反馈</b>在下方写清问题，保存后可复制完整上下文到现有 Agent 会话。外部修改后刷新，本文件会重新进入待复审。</div><div class="reviewcard muted" id="liveOverview" style="font-size:11px;line-height:1.9"></div>';$('#prompt').placeholder='记录当前文件的问题，例如：这里的术语与前文定义不一致，请核对原始课程材料。';$('.composefoot').innerHTML='<button class="outline" id="copyAgent">复制反馈 ↗</button><button class="primary" id="send">保存问题</button>';$('.reviewaction #flag').textContent='⚑ 标记问题';$('#comment').textContent='＋ 为此文件记录反馈';$('#comment').nextElementSibling.textContent='问题绑定文件内容指纹';$('#commit').textContent='导出审查记录 ↓';$('#commit').previousElementSibling.textContent='当前版本只读 Git';$('.footer').innerHTML='<span class="green">●</span> fde-study · 真实工作区<span class="spacer"></span><span>仅读取 Git · 审查记录保存在客户端</span><span>Open Design / 试用版</span>';
$('#prompt').oninput=()=>drafts.set(current,$('#prompt').value);$('#refresh').onclick=refresh;document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>view(b.dataset.view));$('#search').oninput=renderList;$('#filter').onchange=renderList;$('#intent').onclick=()=>{tree=false;$('#intent').classList.add('selected');$('#tree').classList.remove('selected');renderList()};$('#tree').onclick=()=>{tree=true;$('#tree').classList.add('selected');$('#intent').classList.remove('selected');renderList()};$('#approve').onclick=()=>mark(file()?.state==='reviewed'?'pending':'reviewed',file()?.note||'');$('#flag').onclick=()=>mark('issue',$('#prompt').value);$('#next').onclick=()=>{if(!data.files.length)return;const i=data.files.findIndex(f=>f.path===current);current=data.files[(i+1)%data.files.length].path;renderFile();renderList()};$('#baseline').onchange=e=>{baseline=e.target.value;layout='split';renderFile()};$('#diffmode').onclick=()=>{layout=layout==='split'?'document':'split';renderFile()};$('#toggleAgent').onclick=()=>$('#agentpanel').classList.toggle('hidden');$('#closeAgent').onclick=()=>$('#agentpanel').classList.add('hidden');$('#comment').onclick=()=>{$('#agentpanel').classList.remove('hidden');$('#prompt').focus()};$('#send').onclick=()=>{if(!$('#prompt').value.trim())return toast('请先填写当前文件的问题');mark('issue',$('#prompt').value.trim())};async function copyAgent(){const f=file();if(!f)return;const text=`请在本地仓库 ${data.repo} 中处理以下审查反馈。\n文件：${f.path}\n审查基线 HEAD：${data.base}\n审查内容 SHA256：${f.fingerprint}\n\n问题：${$('#prompt').value.trim()||f.note||'请检查此文件的本轮修改，先说明发现与建议。'}\n\n请先核对文件是否已被其他人修改；修改完成后说明变更与验证结果，不执行提交。\n\n当前 Diff：\n${f.patch}`;try{await navigator.clipboard.writeText(text);toast('已复制文件、基线、反馈及真实 Diff，可粘贴到 Claude Code / Codex')}catch{toast('剪贴板不可用，请手动复制反馈')}}$('#copyAgent').onclick=copyAgent;$('#connect').onclick=copyAgent;$('#commit').onclick=exportReview;refresh();
